    // backtrack runs a backtracking search of prog on the input starting at pos.
    gocpp::slice<int> rec::backtrack(Regexp* re, gocpp::slice<unsigned char> ib, gocpp::string is, int pos, int ncap, gocpp::slice<int> dstCap)
    {
        auto startCond = re->cond;
        if(startCond == ~ syntax::EmptyOp(0))
        {
            // impossible
            return nullptr;
        }
        if(startCond & syntax::EmptyBeginText != 0 && pos != 0)
        {
            // Anchored match, past beginning of text.
            return nullptr;
        }

        auto b = newBitState();
        auto [i, end] = rec::init(gocpp::recv(b->inputs), nullptr, ib, is);
        rec::reset(gocpp::recv(b), re->prog, end, ncap);

        // Anchored search must start at the beginning of the input
        if(startCond & syntax::EmptyBeginText != 0)
        {
            if(len(b->cap) > 0)
            {
                b->cap[0] = pos;
            }
            if(! rec::tryBacktrack(gocpp::recv(re), b, i, uint32_t(re->prog->Start), pos))
            {
                freeBitState(b);
                return nullptr;
            }
        }
        else
        {
            // Unanchored search, starting from each possible text position.
            // Notice that we have to try the empty string at the end of
            // the text, so the loop condition is pos <= end, not pos < end.
            // This looks like it's quadratic in the size of the text,
            // but we are not clearing visited between calls to TrySearch,
            // so no work is duplicated and it ends up still being linear.
            auto width = - 1;
            for(; pos <= end && width != 0; pos += width)
            {
                if(len(re->prefix) > 0)
                {
                    // Match requires literal prefix; fast search for it.
                    auto advance = rec::index(gocpp::recv(i), re, pos);
                    if(advance < 0)
                    {
                        freeBitState(b);
                        return nullptr;
                    }
                    pos += advance;
                }

                if(len(b->cap) > 0)
                {
                    b->cap[0] = pos;
                }
                if(rec::tryBacktrack(gocpp::recv(re), b, i, uint32_t(re->prog->Start), pos))
                {
                    // Match must be leftmost; done.
                    goto Match;
                }
                std::tie(std::ignore, width) = rec::step(gocpp::recv(i), pos);
            }
            freeBitState(b);
            return nullptr;
        }

        Match:
        dstCap = append(dstCap, b->matchcap);
        freeBitState(b);
        return dstCap;
    }

